29	    private static final RowMapper<IdempotencyRecord> MAPPER = (rs, rowNum) -> new IdempotencyRecord(
30	            rs.getString("request_id"),
31	            rs.getString("operation"),
32	            rs.getString("request_fingerprint"),
33	            rs.getString("response_json"));
