42	    public Optional<IdempotencyRecord> lockById(String requestId) {
43	        List<IdempotencyRecord> list = jdbc.query(
44	                "SELECT request_id, operation, request_fingerprint, response_json "
45	                        + "FROM idempotency_record WHERE request_id = ? FOR UPDATE",
46	                MAPPER, requestId);
47	        return list.stream().findFirst();
