51	    public Optional<IdempotencyRecord> findById(String requestId) {
52	        List<IdempotencyRecord> list = jdbc.query(
53	                "SELECT request_id, operation, request_fingerprint, response_json "
54	                        + "FROM idempotency_record WHERE request_id = ?",
55	                MAPPER, requestId);
56	        return list.stream().findFirst();
57	    }
